function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.folder}"/></svg>`;}
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);el.removeAttribute('data-icon');});}
const person=id=>DEMO.people.find(p=>p.id===id)||DEMO.people[0];
const project=id=>DEMO.projects.find(p=>p.id===id)||DEMO.projects[0];
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatDate=(date,options={day:'numeric',month:'short'})=>new Date(`${date}T12:00:00`).toLocaleDateString('en-GB',options);
const avatar=(id,extra='')=>{const p=person(id);return `<span class="avatar avatar-${p.color} ${extra}" title="${escapeHTML(p.name)}" aria-label="${escapeHTML(p.name)}">${p.initials}</span>`;};
const avatars=ids=>`<div class="avatars" aria-label="Project members">${ids.map(id=>avatar(id)).join('')}</div>`;
const badge=status=>`<span class="status-badge ${status==='At risk'?'clay':['Planning','In review'].includes(status)?'blue':status==='Backlog'?'gray':''}">${escapeHTML(status)}</span>`;
const progress=p=>`<div class="progress-cell"><div class="progress-track" role="progressbar" aria-label="${escapeHTML(p.name)} progress" aria-valuenow="${p.progress}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill ${p.color}" style="width:${p.progress}%"></div></div><span>${p.progress}%</span></div>`;
const priority=value=>`<span class="priority ${value.toLowerCase()}">${value}</span>`;
const projectSymbol=p=>`<span class="project-symbol ${p.color}">${icon(p.id==='brand-refresh'?'file':p.id==='people-onboarding'?'users':p.id==='quarterly-planning'?'flag':'folder')}</span>`;
const primaryButton=(label,action='new-project',iconName='plus')=>`<button class="button button-primary" data-action="${action}">${icon(iconName)}${label}</button>`;
const heading=(title,description,button='',eyebrow='YOUR WORKSPACE, CONSIDERED')=>`<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${button}</div></div>`;
const sectionHeading=(title,link='',href='')=>`<div class="section-heading"><h2>${title}</h2>${link?`<a class="text-link" href="#${href}">${link}${icon('arrow')}</a>`:''}</div>`;
const architecture=`<svg class="architecture" viewBox="0 0 280 160" fill="none" aria-hidden="true"><ellipse cx="155" cy="153" rx="132" ry="7" fill="#dfe3d1"/><path d="M52 151V65L155 18l102 47v86H52Z" fill="#e5e8d9"/><path d="m44 64 111-51 110 51M57 70h195M57 77h195M60 149h192" stroke="#bac1a7"/><path d="M111 150V89a44 44 0 0 1 88 0v61" fill="#d7ddc7" stroke="#b5bea0"/><path d="M123 150V91a32 32 0 0 1 64 0v59" fill="#e9ecdf" stroke="#b5bea0"/><path d="M137 150V94a18 18 0 0 1 36 0v56" fill="#c7d0b4" stroke="#b5bea0"/><path d="M66 150V99a15 15 0 0 1 30 0v51M214 150V99a15 15 0 0 1 30 0v51" stroke="#b5bea0"/><path d="M73 150V100a8 8 0 0 1 16 0v50M221 150V100a8 8 0 0 1 16 0v50M155 20v22M107 42h96M123 34h64M32 153h238" stroke="#c1c8ae"/><path d="M26 151v-24m0 15c-14-2-18-13-15-19 12 0 17 8 15 19Zm1-8c12-4 16-14 11-20-10 3-14 12-11 20Z" stroke="#a6b28e"/><path d="M21 152h13l-2-14h-9l-2 14Z" fill="#cbd3ba"/><path d="M256 152h14l-2-17h-10l-2 17Z" fill="#cbd3ba"/><path d="M263 138v-30m0 13c-10-4-13-14-9-20 9 4 12 12 9 20Zm0 8c12-4 16-14 12-20-11 3-15 12-12 20Z" stroke="#a6b28e"/></svg>`;

const state={page:'overview',taskView:'list',taskScope:'mine',taskStatus:'all',projectView:'grid',projectStatus:'all',overviewTab:'upcoming',knowledgeType:'all',settingsTab:'general',timelineScale:'weeks'};
const pageTitles={overview:'Overview',tasks:'My work',projects:'Projects',timeline:'Timeline',discussions:'Discussions',knowledge:'Knowledge',team:'Team',reports:'Reports',settings:'Settings'};
let toastTimer;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500);}
function statsCards(){const done=DEMO.tasks.filter(t=>t.status==='Done').length;const onTrack=DEMO.projects.filter(p=>p.status==='On track').length;return `<div class="stats-grid">${[
  ['Active projects',DEMO.projects.length,'folder',`${onTrack} on track`,'trend',false],
  ['Work completed',done,'check-circle','Across all projects','check',false],
  ['In progress',DEMO.tasks.filter(t=>t.status==='In progress').length,'clock','Moving things forward','arrow',true],
  ['Team members',DEMO.people.length,'users','Good work, together','users',true]
].map(([label,value,i,change,ci,neutral])=>`<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(i)}</span></div><div class="stat-bottom"><strong class="stat-number">${value.toString().padStart(2,'0')}</strong><span class="stat-change ${neutral?'neutral':''}">${icon(ci)}${change}</span></div></div>`).join('')}</div>`;}
function projectTable(items=DEMO.projects){return `<div class="projects-table-wrap"><table class="data-table"><thead><tr><th>Project name</th><th>Status</th><th>Progress</th><th class="members-column">Team</th><th class="due-column">Due date</th></tr></thead><tbody>${items.map(p=>`<tr class="clickable-row" data-action="project" data-id="${p.id}" tabindex="0" aria-label="Open ${escapeHTML(p.name)}"><td><div class="project-cell">${projectSymbol(p)}<div><span class="project-name">${escapeHTML(p.name)}</span><span class="project-category">${escapeHTML(p.category)}</span></div></div></td><td>${badge(p.status)}</td><td>${progress(p)}</td><td class="members-column">${avatars(p.members)}</td><td class="due-column"><span class="table-date">${formatDate(p.due)}</span></td></tr>`).join('')}</tbody></table></div>`;}
function taskRow(t,full=false){const p=project(t.project);return `<div class="task-item" data-action="task" data-id="${t.id}" tabindex="0" aria-label="Open ${escapeHTML(t.title)}"><button class="task-checkbox ${t.status==='Done'?'done':''}" data-action="toggle-task" data-id="${t.id}" aria-label="${t.status==='Done'?'Reopen':'Complete'} ${escapeHTML(t.title)}" aria-pressed="${t.status==='Done'}">${t.status==='Done'?icon('check'):''}</button><div class="task-title ${t.status==='Done'?'done':''}">${escapeHTML(t.title)}<span class="task-project"><span class="project-dot ${p.color}"></span>${escapeHTML(p.name)}${full?` <span>· ${t.id}</span>`:''}</span></div>${priority(t.priority)}${full?badge(t.status):''}${full?avatar(t.assignee):''}<span class="task-date ${t.due<='2026-11-18'&&t.status!=='Done'?'due-soon':''}">${t.due==='2026-11-16'?'Today':formatDate(t.due)}</span></div>`;}
function activityList(){return DEMO.activity.map(a=>`<div class="activity-item">${avatar(a.person)}<div class="activity-text"><strong>${person(a.person).name.split(' ')[0]}</strong> ${escapeHTML(a.text)} <button class="text-link activity-project" data-action="project" data-id="${a.project}">${escapeHTML(project(a.project).name)}</button><div class="activity-time">${a.time}</div></div></div>`).join('');}
function milestoneRow(m){return `<button class="milestone-item" data-action="milestone" data-id="${m.id}" style="width:100%;text-align:left"><span class="milestone-date"><small>${formatDate(m.due,{month:'short'}).toUpperCase()}</small><strong>${formatDate(m.due,{day:'numeric'})}</strong></span><span class="milestone-description"><strong>${escapeHTML(m.title)}</strong><small>${escapeHTML(project(m.project).name)}</small></span>${icon('chevron')}</button>`;}
function overview(){let tasks=DEMO.tasks.filter(t=>state.overviewTab==='completed'?t.status==='Done':state.overviewTab==='mine'?t.assignee==='eleanor'&&t.status!=='Done':t.status!=='Done').slice(0,4);return `${heading('Good morning, Eleanor.','A clear view of your people, projects, and the possibilities ahead.',`<span class="date-display">${icon('calendar')}Monday, 16 November</span>${primaryButton('New project')}`,'MONDAY, 16 NOVEMBER 2026')}
  <section class="welcome-card" aria-label="Workspace introduction"><div class="welcome-copy"><div class="eyebrow">A SPACE FOR GOOD WORK</div><h2>Great things take shape, together.</h2><p>Your plans, your people, your progress. All in one considered place.</p><a href="#projects" class="text-link">Explore your projects ${icon('arrow')}</a></div>${architecture}</section>
  ${statsCards()}<div class="dashboard-grid"><div class="content-stack"><section>${sectionHeading('Projects in focus','All projects','projects')}${projectTable(DEMO.projects.slice(0,4))}</section><section>${sectionHeading('A little focus for today','View all work','tasks')}<div class="tasks-panel"><div class="tabs task-tabs"><button class="${state.overviewTab==='upcoming'?'active':''}" data-action="overview-tab" data-value="upcoming">Upcoming <span class="tab-count">${DEMO.tasks.filter(t=>t.status!=='Done').length}</span></button><button class="${state.overviewTab==='mine'?'active':''}" data-action="overview-tab" data-value="mine">Assigned to me</button><button class="${state.overviewTab==='completed'?'active':''}" data-action="overview-tab" data-value="completed">Completed</button></div>${tasks.length?tasks.map(t=>taskRow(t)).join(''):'<div class="empty-state"><p>You are all caught up.</p></div>'}</div></section></div><aside class="aside-stack"><section class="panel"><div class="panel-header"><h2>Around the workspace</h2><span class="subtle-label">Today</span></div><div class="activity-list">${activityList()}</div><div class="activity-footer"><button class="text-link" data-action="activity">View all activity ${icon('arrow')}</button></div></section><section class="panel"><div class="panel-header"><h2>On the horizon</h2><a class="text-link" href="#timeline">Timeline ${icon('arrow')}</a></div><div class="milestones-list">${DEMO.milestones.slice(0,3).map(milestoneRow).join('')}</div></section><div class="quote-note"><p>“Well done is better<br>than well said.”</p><span>A LITTLE INSPIRATION FOR YOUR DAY</span></div></aside></div>`;}
function projectsPage(){const filtered=DEMO.projects.filter(p=>state.projectStatus==='all'||p.status===state.projectStatus);return `${heading('Room for your next great idea.','A shared view of everything taking shape across your organisation.',primaryButton('New project'),'PROJECTS & PORTFOLIOS')}<div class="toolbar"><div class="filter-controls"><select class="filter-select" id="project-status" aria-label="Filter projects by status"><option value="all">All projects (${DEMO.projects.length})</option>${['On track','At risk','Planning'].map(s=>`<option ${state.projectStatus===s?'selected':''}>${s}</option>`).join('')}</select><span class="subtle-label">${filtered.length} projects</span></div><div class="view-switch" aria-label="Project display"><button class="${state.projectView==='grid'?'active':''}" data-action="project-view" data-value="grid">${icon('overview')}Grid</button><button class="${state.projectView==='list'?'active':''}" data-action="project-view" data-value="list">${icon('list')}List</button></div></div>${state.projectView==='list'?projectTable(filtered):`<div class="project-grid">${filtered.map(p=>`<article class="project-card" tabindex="0" data-action="project" data-id="${p.id}" aria-label="Open ${escapeHTML(p.name)}"><div class="project-card-top">${projectSymbol(p)}${badge(p.status)}</div><h2>${escapeHTML(p.name)}</h2><p>${escapeHTML(p.description)}</p>${progress(p)}<div class="project-card-footer">${avatars(p.members)}<span class="table-date">${icon('calendar',11)} ${formatDate(p.due)}</span></div></article>`).join('')}</div>`}`;}
function boardCard(t){const p=project(t.project);return `<article class="board-card" tabindex="0" data-action="task" data-id="${t.id}"><span class="task-project"><span class="project-dot ${p.color}"></span>${escapeHTML(p.name)}</span><h3>${escapeHTML(t.title)}</h3><p class="board-card-id">${t.id}</p><div class="board-card-footer">${priority(t.priority)}<div class="board-card-meta"><span class="task-date">${formatDate(t.due)}</span>${avatar(t.assignee)}</div></div></article>`;}
function tasksPage(){const filtered=DEMO.tasks.filter(t=>(state.taskScope==='all'||t.assignee==='eleanor')&&(state.taskStatus==='all'||t.status===state.taskStatus));return `${heading('A little focus goes a long way.','A clear place for the work that needs your attention.',primaryButton('Add work','new-task'),'MY WORK')}<div class="toolbar"><div class="filter-controls"><select class="filter-select" id="task-scope" aria-label="Filter work by assignment"><option value="mine" ${state.taskScope==='mine'?'selected':''}>Assigned to me</option><option value="all" ${state.taskScope==='all'?'selected':''}>All team work</option></select><select class="filter-select" id="task-status" aria-label="Filter work by status"><option value="all">All statuses</option>${['Backlog','In progress','In review','Done'].map(s=>`<option ${state.taskStatus===s?'selected':''}>${s}</option>`).join('')}</select><span class="subtle-label">${filtered.length} items</span></div><div class="view-switch"><button class="${state.taskView==='list'?'active':''}" data-action="task-view" data-value="list">${icon('list')}List</button><button class="${state.taskView==='board'?'active':''}" data-action="task-view" data-value="board">${icon('board')}Board</button></div></div>${state.taskView==='board'?`<div class="board">${['Backlog','In progress','In review','Done'].map(status=>`<section class="board-column"><div class="board-heading"><span>${status}<span class="board-count">${filtered.filter(t=>t.status===status).length}</span></span><button class="icon-button" data-action="new-task" data-status="${status}" aria-label="Add work to ${status}">${icon('plus')}</button></div>${filtered.filter(t=>t.status===status).map(boardCard).join('')||'<div class="empty-state" style="padding:28px 5px"><p>A little room for what’s next.</p></div>'}</section>`).join('')}</div>`:filtered.length?`<div class="panel tasks-full">${filtered.map(t=>taskRow(t,true)).join('')}</div>`:'<div class="panel empty-state"><h2>A clear space.</h2><p>No work matches these filters.</p></div>'}`;}
function timelinePage(){const labels=state.timelineScale==='weeks'?['2–8 Nov','9–15 Nov','16–22 Nov','23–29 Nov','30 Nov–6 Dec','7–13 Dec']:['September','October','November','December','January','February'];return `${heading('See the bigger picture.','A little perspective on what is happening, and what comes next.',primaryButton('Add milestone','new-milestone'),'TIMELINE & MILESTONES')}<div class="toolbar"><span class="subtle-label">${state.timelineScale==='weeks'?'November – December 2026':'September 2026 – February 2027'} · All projects</span><div class="view-switch"><button class="${state.timelineScale==='weeks'?'active':''}" data-action="timeline-scale" data-value="weeks">Weeks</button><button class="${state.timelineScale==='months'?'active':''}" data-action="timeline-scale" data-value="months">Months</button></div></div><div class="timeline-panel"><div class="timeline-table"><div class="timeline-top"><div>Projects & initiatives</div>${labels.map(l=>`<div>${l}</div>`).join('')}</div>${DEMO.projects.map((p,index)=>{const start=state.timelineScale==='weeks'?(index===5?3:index===4?2:1):2;const end=state.timelineScale==='weeks'?(index===3?4:index===5?6:5):5;return `<div class="timeline-row"><button class="timeline-project" data-action="project" data-id="${p.id}">${projectSymbol(p)}<span class="project-name">${escapeHTML(p.name)}</span></button><div class="timeline-track"><button class="timeline-bar ${p.color}" style="grid-column:${start}/${end}" data-action="project" data-id="${p.id}">${p.progress}% complete</button></div></div>`;}).join('')}<div class="timeline-caption">${icon('info',13)}Illustrative project durations for this presentation. Target dates appear in each project.</div></div></div><div style="margin-top:28px">${sectionHeading('Moments that matter')}<div class="milestone-grid">${DEMO.milestones.map(m=>`<div class="milestone-card">${milestoneRow(m)}</div>`).join('')}</div></div>`;}
function teamPage(){return `${heading('Good work begins with good people.','The people, perspectives and possibilities behind every project.',primaryButton('Invite a colleague','invite'),'PEOPLE & TEAMS')}<div class="toolbar"><span class="subtle-label">${DEMO.people.length} people · ${new Set(DEMO.people.map(p=>p.team)).size} teams</span><span class="status-badge">Meridian & Co. workspace</span></div><div class="team-grid">${DEMO.people.map(p=>`<article class="person-card">${avatar(p.id)}<h2>${p.name}</h2><p>${p.role}</p><span class="person-team">${p.team}</span><div class="person-card-footer"><span class="online-dot">Workspace member</span><button class="text-link" data-action="person" data-id="${p.id}">View profile ${icon('arrow',12)}</button></div></article>`).join('')}</div>`;}
function knowledgePage(){const filtered=DEMO.documents.filter(d=>state.knowledgeType==='all'||d.type===state.knowledgeType);return `${heading('A little shared understanding.','A home for the ideas, decisions and knowledge worth keeping.',primaryButton('New page','new-document'),'KNOWLEDGE & RESOURCES')}<div class="toolbar"><div class="filter-controls"><select class="filter-select" id="knowledge-type" aria-label="Filter knowledge by type"><option value="all">All resources</option>${[...new Set(DEMO.documents.map(d=>d.type))].map(s=>`<option ${state.knowledgeType===s?'selected':''}>${s}</option>`).join('')}</select><span class="subtle-label">${filtered.length} pages</span></div><button class="text-link" data-action="search">${icon('search')}Find a page</button></div><div class="knowledge-grid">${filtered.map(d=>`<article class="document-card" data-action="document" data-id="${d.id}" tabindex="0"><div class="document-icon">${icon('file')}</div><span class="eyebrow">${d.type.toUpperCase()}</span><h2>${escapeHTML(d.name)}</h2><p>${escapeHTML(project(d.project).name)}</p><div class="document-meta"><span>${avatar(d.owner)} ${person(d.owner).name.split(' ')[0]}</span><span>${formatDate(d.updated)} · ${d.size}</span></div></article>`).join('')}</div>`;}
function discussionsPage(){return `${heading('Make room for a conversation.','Share a thought. Ask a question. Keep everyone in the picture.',primaryButton('Start a discussion','new-discussion'),'DISCUSSIONS & UPDATES')}<div class="toolbar"><span class="subtle-label">${DEMO.discussions.length} conversations across your workspace</span><button class="text-link" data-action="search">${icon('search')}Find a conversation</button></div><div class="panel">${DEMO.discussions.map(d=>`<article class="discussion-card" tabindex="0" data-action="discussion" data-id="${d.id}">${avatar(d.author)}<div class="discussion-content"><h2>${escapeHTML(d.title)}</h2><p>${escapeHTML(d.excerpt)}</p><div class="discussion-meta"><strong>${person(d.author).name}</strong><span>${escapeHTML(project(d.project).name)}</span><span>${d.updated}</span></div></div><div class="discussion-replies">${icon('message')}<strong>${d.replies}</strong><span>replies</span></div></article>`).join('')}</div>`;}
function reportsPage(){const counts=['Done','In progress','In review','Backlog'].map(s=>DEMO.tasks.filter(t=>t.status===s).length);const total=DEMO.tasks.length;const angles=counts.map((_,i)=>counts.slice(0,i+1).reduce((a,b)=>a+b,0)/total*360);return `${heading('Clarity, with a little perspective.','An honest view of progress, project health and the work ahead.','<button class="button" data-action="export">'+icon('download')+'Export summary</button>','REPORTS & INSIGHTS')}${statsCards()}<div class="report-grid"><section class="report-card"><h2>Where things stand</h2><p>Completion across the ${DEMO.projects.length} projects in this workspace.</p><div class="bar-chart" role="img" aria-label="${escapeHTML(DEMO.projects.map(p=>`${p.name}: ${p.progress}% complete`).join('; '))}">${DEMO.projects.map(p=>`<div class="chart-column"><span>${p.progress}%</span><div class="chart-bar" style="height:${p.progress}%"></div><small>${p.name.split(' ')[0]}</small></div>`).join('')}</div><div class="chart-caption">Sample project progress · Snapshot: 16 November 2026</div></section><section class="report-card"><h2>A balance of good work</h2><p>Work items grouped by their current workflow status.</p><div class="donut-wrap"><div class="donut" style="--done-angle:${angles[0]}deg;--progress-angle:${angles[1]}deg;--review-angle:${angles[2]}deg" role="img" aria-label="${counts[0]} done, ${counts[1]} in progress, ${counts[2]} in review, ${counts[3]} backlog"><div class="donut-center">${total}<small>work items</small></div></div><div class="chart-legend">${['Done','In progress','In review','Backlog'].map((s,i)=>`<div class="legend-item"><i style="background:${['#849c6e','#b6c4a4','#dbc8a7','#e9eddf'][i]}"></i>${s}<strong>${counts[i]}</strong></div>`).join('')}</div></div><div class="chart-caption">All projects · Counts reflect the sample work items shown.</div></section></div><div style="margin-top:27px">${sectionHeading('Project health at a glance')}${projectTable()}</div>`;}
function settingsPage(){let content='';if(state.settingsTab==='general')content=`<h2>The details that make it yours.</h2><p>Organisation profile and workspace preferences.</p><form id="settings-form"><div class="form-grid"><div class="form-field"><label for="org-name">Organisation name</label><input id="org-name" name="organisation" value="Meridian & Co." required></div><div class="form-field"><label for="workspace-name">Workspace name</label><input id="workspace-name" value="Enterprise workspace" required></div><div class="form-field"><label for="timezone">Time zone</label><select id="timezone"><option>Asia/Kolkata (GMT+05:30)</option><option>Europe/London (GMT+00:00)</option><option>Europe/Rome (GMT+01:00)</option></select></div><div class="form-field"><label for="language">Language</label><select id="language"><option>English (United Kingdom)</option><option>English (India)</option><option>Italiano</option></select></div></div><div class="form-field"><label for="workspace-description">A few words about your workspace</label><textarea id="workspace-description">A shared space for good work, thoughtful collaboration and a clear view of progress.</textarea></div><p class="demo-note">${icon('info')}Preview settings only. Changes are not saved to a server.</p><button class="button button-primary" type="submit">Save preview</button></form>`;else if(state.settingsTab==='notifications')content=`<h2>A little less noise.</h2><p>Choose the updates that deserve your attention.</p>${[['Work assigned to me','Know when something new needs your attention.'],['Project milestones','Keep important moments on your radar.'],['Discussion mentions','Join the conversations you are part of.'],['Weekly workspace digest','A considered overview, once a week.']].map(([t,d])=>`<label class="setting-row"><span><strong>${t}</strong><p>${d}</p></span><input class="toggle" type="checkbox" checked aria-label="${t}"></label>`).join('')}<p class="demo-note" style="margin-top:20px">${icon('info')}Notification preferences are for visual demonstration.</p>`;else content=`<h2>Thoughtful by design.</h2><p>A preview of the organisation controls planned for Forma.</p>${[['shield','Identity & access','Single sign-on, roles and workspace membership.'],['file','Audit & governance','A clear history of administrative changes.'],['globe','Integrations','Bring your existing tools into the conversation.'],['folder','Data & retention','Manage your organisation’s content lifecycle.']].map(([i,t,d])=>`<div class="setting-row"><span style="display:flex;gap:13px;align-items:center">${icon(i,20)}<span><strong>${t}</strong><p>${d}</p></span></span><span class="status-badge gray">Planned</span></div>`).join('')}<p class="demo-note" style="margin-top:20px">${icon('info')}Enterprise controls are presentation concepts.</p>`;return `${heading('A workspace that feels like yours.','The considered details behind a better working day.','','WORKSPACE SETTINGS')}<div class="settings-grid"><div class="settings-nav" aria-label="Settings sections">${[['general','General'],['notifications','Notifications'],['enterprise','Enterprise controls']].map(([id,label])=>`<button class="${state.settingsTab===id?'active':''}" data-action="settings-tab" data-value="${id}">${label}</button>`).join('')}</div><section class="settings-form">${content}</section></div>`;}
const renderers={overview,projects:projectsPage,tasks:tasksPage,timeline:timelinePage,team:teamPage,knowledge:knowledgePage,discussions:discussionsPage,reports:reportsPage,settings:settingsPage};
function render(){document.getElementById('main-content').innerHTML=`<div class="fade-in">${renderers[state.page]()}</div>`;document.getElementById('breadcrumb').textContent=pageTitles[state.page];document.title=`${pageTitles[state.page]} · Forma`;document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===state.page);if(a.dataset.page===state.page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.getElementById('my-work-count').textContent=DEMO.tasks.filter(t=>t.assignee==='eleanor'&&t.status!=='Done').length;}
function navigate(){if(location.hash==='#main-content'){document.getElementById('main-content').focus();return;}const page=location.hash.slice(1).split('?')[0]||'overview';state.page=renderers[page]?page:'overview';render();closeMenu();window.scrollTo(0,0);}
function closeMenu(){document.getElementById('sidebar').classList.remove('open');document.getElementById('sidebar-backdrop').classList.remove('visible');document.getElementById('menu-button').setAttribute('aria-expanded','false');}
const modal=document.getElementById('modal');
let returnFocus=null;
function openModal(title,subtitle,body,footer=''){returnFocus=document.activeElement;document.getElementById('modal-content').innerHTML=`<div class="modal-body"><div class="modal-heading"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}</div>`;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();if(returnFocus?.isConnected)returnFocus.focus();}
const cancelButton='<button class="button" type="button" data-action="close-modal">Cancel</button>';
const demoNote=`<div class="demo-note">${icon('info')}This is a frontend preview. Sample changes reset on refresh.</div>`;
function openProject(id){const p=project(id),tasks=DEMO.tasks.filter(t=>t.project===id);openModal(escapeHTML(p.name),escapeHTML(p.category),`${badge(p.status)}<p class="detail-description">${escapeHTML(p.description)}</p><div class="detail-progress">${progress(p)}</div><dl class="detail-stats"><div><dt>Project owner</dt><dd>${avatar(p.owner)}${person(p.owner).name}</dd></div><div><dt>Target date</dt><dd>${icon('calendar',14)}${formatDate(p.due,{day:'numeric',month:'long',year:'numeric'})}</dd></div><div><dt>Working together</dt><dd>${avatars(p.members)}</dd></div><div><dt>Work items</dt><dd>${tasks.filter(t=>t.status==='Done').length} of ${tasks.length} completed</dd></div></dl><div class="detail-tasks"><h3>Work taking shape</h3>${tasks.map(t=>taskRow(t)).join('')||'<p class="detail-description">A fresh space for your next great idea.</p>'}</div>`,`<button class="button" data-action="project-timeline">${icon('timeline')}View timeline</button><button class="button button-primary" data-action="project-board">${icon('board')}Explore team board</button>`);}
function openTask(id){const t=DEMO.tasks.find(t=>t.id===id);if(!t)return;openModal(escapeHTML(t.title),`${t.id} · ${escapeHTML(project(t.project).name)}`,`<form id="edit-task-form" data-id="${t.id}"><dl class="detail-stats"><div><dt>Assigned to</dt><dd>${avatar(t.assignee)}${person(t.assignee).name}</dd></div><div><dt>Due date</dt><dd>${formatDate(t.due,{day:'numeric',month:'long',year:'numeric'})}</dd></div></dl><div class="form-grid"><div class="form-field"><label for="edit-status">Status</label><select id="edit-status" name="status">${['Backlog','In progress','In review','Done'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="form-field"><label for="edit-priority">Priority</label><select id="edit-priority" name="priority">${['High','Medium','Low'].map(s=>`<option ${t.priority===s?'selected':''}>${s}</option>`).join('')}</select></div></div>${demoNote}<div class="modal-footer">${cancelButton}<button class="button button-primary" type="submit">Update preview</button></div></form>`);}
function createProject(){openModal('Room for something new.','Give your next project a place to take shape.',`<form id="new-project-form"><div class="form-field"><label for="new-project-name">Project name</label><input id="new-project-name" name="name" placeholder="What are we working towards?" maxlength="65" required autofocus></div><div class="form-field"><label for="new-project-description">A few words about it</label><textarea id="new-project-description" name="description" placeholder="The purpose, the possibility, the bigger picture…" maxlength="280"></textarea></div><div class="form-grid"><div class="form-field"><label for="new-project-owner">Project owner</label><select id="new-project-owner" name="owner">${DEMO.people.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div class="form-field"><label for="new-project-due">Target date</label><input type="date" id="new-project-due" name="due" value="2026-11-30" required></div></div>${demoNote}<div class="modal-footer">${cancelButton}<button class="button button-primary" type="submit">Create preview project</button></div></form>`);}
function createTask(status='Backlog'){openModal('A little work, a little progress.','Add a work item to the presentation.',`<form id="new-task-form"><div class="form-field"><label for="new-task-title">What needs to happen?</label><input id="new-task-title" name="title" placeholder="A clear, simple description" maxlength="100" required autofocus></div><div class="form-field"><label for="new-task-project">Project</label><select id="new-task-project" name="project">${DEMO.projects.map(p=>`<option value="${p.id}">${escapeHTML(p.name)}</option>`).join('')}</select></div><div class="form-grid"><div class="form-field"><label for="new-task-person">Assigned to</label><select name="assignee" id="new-task-person">${DEMO.people.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select></div><div class="form-field"><label for="new-task-due">Due date</label><input type="date" id="new-task-due" name="due" value="2026-11-20" required></div><div class="form-field"><label for="new-task-status">Status</label><select id="new-task-status" name="status">${['Backlog','In progress','In review','Done'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></div><div class="form-field"><label for="new-task-priority">Priority</label><select id="new-task-priority" name="priority"><option>Medium</option><option>High</option><option>Low</option></select></div></div>${demoNote}<div class="modal-footer">${cancelButton}<button class="button button-primary" type="submit">Add to preview</button></div></form>`);}
function openDocument(id){const d=DEMO.documents.find(d=>d.id===id);if(!d)return;const body=d.content?`<p>${escapeHTML(d.content).replace(/\n/g,'<br>')}</p>`:`<h3>A shared point of view</h3><p>Good work begins with a clear understanding of what we are here to achieve. This space brings together the principles and decisions behind ${escapeHTML(project(d.project).name.toLowerCase())}.</p><h3>What matters to us</h3><ul><li>Keep our clients and colleagues at the heart of each decision.</li><li>Make ownership clear and progress easy to understand.</li><li>Capture what we learn, and make room to improve.</li></ul><h3>What comes next</h3><p>Review this page with the project team, agree the next steps and link the work that brings these ideas to life.</p>`;openModal(escapeHTML(d.name),`${person(d.owner).name} · ${formatDate(d.updated)} · ${d.size}`,`${badge(d.type)}<div class="document-preview">${body}</div><div style="margin-top:17px">${demoNote}</div>`);}
function openDiscussion(id){const d=DEMO.discussions.find(d=>d.id===id);if(!d)return;openModal(escapeHTML(d.title),`${person(d.author).name} · ${escapeHTML(project(d.project).name)}`,`<div style="display:flex;gap:12px;align-items:center">${avatar(d.author)}<span class="subtle-label">${d.updated}</span></div><p class="detail-description">${escapeHTML(d.excerpt)}</p><div class="document-preview"><h3>A conversation in progress</h3><p>This preview shows where ${d.replies} replies, team feedback and shared decisions would appear.</p></div><form id="reply-form"><div class="form-field" style="margin-top:20px"><label for="discussion-reply">Add your thoughts</label><textarea id="discussion-reply" placeholder="A little perspective goes a long way…" required maxlength="500"></textarea></div><div class="modal-footer">${cancelButton}<button class="button button-primary">Preview reply</button></div></form>`);}
function openPerson(id){const p=person(id);openModal('A good person to know.','Meridian & Co. · Team directory',`<div class="profile-detail">${avatar(id)}<h3>${p.name}</h3><p>${p.role}</p><p>${p.team}</p></div><dl class="detail-stats"><div><dt>Project membership</dt><dd>${DEMO.projects.filter(pr=>pr.members.includes(id)).length} projects</dd></div><div><dt>Open work items</dt><dd>${DEMO.tasks.filter(t=>t.assignee===id&&t.status!=='Done').length} items</dd></div></dl>${demoNote}`);}
function openSearch(){returnFocus=document.activeElement;document.getElementById('modal-content').innerHTML=`<h2 id="modal-title" class="sr-only" style="position:absolute;clip-path:inset(50%);height:1px;width:1px;overflow:hidden">Search the workspace</h2><div class="search-input-wrap">${icon('search')}<input id="global-search" type="search" placeholder="Find projects, work, people or knowledge…" aria-label="Search workspace" autocomplete="off"><button class="icon-button" data-action="close-modal" aria-label="Close search">${icon('close')}</button></div><div id="search-results" class="search-results"><div class="search-hint">A little clarity is just a search away.<br>Try “brand”, “Eleanor” or “report”.</div></div>`;if(!modal.open)modal.showModal();document.getElementById('global-search').focus();}
function search(query){const q=query.trim().toLowerCase();const results=[...DEMO.projects.map(p=>({name:p.name,detail:'Project · '+p.category,action:'project',id:p.id,i:'folder'})),...DEMO.tasks.map(t=>({name:t.title,detail:t.id+' · '+project(t.project).name,action:'task',id:t.id,i:'check-circle'})),...DEMO.people.map(p=>({name:p.name,detail:p.role,action:'person',id:p.id,i:'users'})),...DEMO.documents.map(d=>({name:d.name,detail:'Knowledge · '+d.type,action:'document',id:d.id,i:'file'})),...DEMO.discussions.map(d=>({name:d.title,detail:'Discussion · '+project(d.project).name,action:'discussion',id:d.id,i:'message'}))].filter(r=>q&&(r.name+' '+r.detail).toLowerCase().includes(q)).slice(0,12);document.getElementById('search-results').innerHTML=results.length?results.map(r=>`<button class="search-result" data-action="${r.action}" data-id="${r.id}">${icon(r.i)}<span><strong>${escapeHTML(r.name)}</strong><small>${escapeHTML(r.detail)}</small></span></button>`).join(''):`<div class="search-hint">${q?'Nothing here just yet. Try a different word.':'Try a project, a person or a work item.'}</div>`;}
function simpleForm(kind){const configs={invite:['Good work is better together.','Invite a colleague to your workspace.','Colleague’s email','email','name@organisation.com','Send preview invite'],document:['A thought worth keeping.','Create a page in your shared knowledge space.','Page title','text','What would you like to share?','Create preview page'],discussion:['Start with a conversation.','Give your team something to think about.','Discussion title','text','What is on your mind?','Start preview discussion'],milestone:['A moment to work towards.','Give an important date a little clarity.','Milestone name','text','What are we working towards?','Add preview milestone']};const [title,sub,label,type,placeholder,submit]=configs[kind];openModal(title,sub,`<form id="simple-form" data-kind="${kind}"><div class="form-field"><label for="simple-title">${label}</label><input id="simple-title" name="title" type="${type}" placeholder="${placeholder}" maxlength="100" required autofocus></div>${kind!=='invite'?`<div class="form-field"><label for="simple-project">Project</label><select id="simple-project" name="project">${DEMO.projects.map(p=>`<option value="${p.id}">${escapeHTML(p.name)}</option>`).join('')}</select></div>`:''}${kind==='milestone'?'<div class="form-field"><label for="milestone-due">Target date</label><input type="date" id="milestone-due" name="due" value="2026-11-30" required></div>':kind!=='invite'?'<div class="form-field"><label for="simple-content">Your thoughts</label><textarea id="simple-content" name="content" placeholder="A little context for your colleagues…" maxlength="2000" required></textarea></div>':''}${demoNote}<div class="modal-footer">${cancelButton}<button class="button button-primary">${submit}</button></div></form>`);}
function exportSummary(){const text=`FORMA · MERIDIAN & CO.\nPresentation prototype — sample data\nSnapshot: 16 November 2026\n\n${DEMO.projects.map(p=>`${p.name}: ${p.status} · ${p.progress}% · Due ${formatDate(p.due)}\nOwner: ${person(p.owner).name}`).join('\n\n')}\n\n${DEMO.tasks.length} sample work items · ${DEMO.people.length} sample members\nThis is a frontend concept. No live organisational data is connected.\n`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Forma-presentation-summary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample workspace summary downloaded.');}

document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const {action,id,value}=target.dataset;switch(action){
  case 'close-modal':closeModal();break;
  case 'project':openProject(id);break;
  case 'task':openTask(id);break;
  case 'person':openPerson(id);break;
  case 'document':openDocument(id);break;
  case 'discussion':openDiscussion(id);break;
  case 'new-project':createProject();break;
  case 'new-task':createTask(target.dataset.status);break;
  case 'invite':simpleForm('invite');break;
  case 'new-document':simpleForm('document');break;
  case 'new-discussion':simpleForm('discussion');break;
  case 'new-milestone':simpleForm('milestone');break;
  case 'search':openSearch();break;
  case 'toggle-task':{event.stopPropagation();const t=DEMO.tasks.find(t=>t.id===id);if(t){t.status=t.status==='Done'?'In progress':'Done';render();if(modal.open)openProject(t.project);toast(t.status==='Done'?'A little progress. Work marked complete in this preview.':'Work reopened in this preview.');}break;}
  case 'overview-tab':state.overviewTab=value;render();break;
  case 'project-view':state.projectView=value;render();break;
  case 'task-view':state.taskView=value;render();break;
  case 'settings-tab':state.settingsTab=value;render();break;
  case 'timeline-scale':state.timelineScale=value;render();break;
  case 'project-timeline':closeModal();location.hash='timeline';break;
  case 'project-board':closeModal();state.taskView='board';state.taskScope='all';state.taskStatus='all';location.hash='tasks';if(state.page==='tasks')render();break;
  case 'activity':openModal('A little of what is happening.','Recent updates from across the workspace.',`<div class="notification-list">${activityList()}</div>`);break;
  case 'milestone':{const m=DEMO.milestones.find(item=>item.id===id);openModal(escapeHTML(m.title),escapeHTML(project(m.project).name),`${badge(m.status)}<dl class="detail-stats"><div><dt>Target date</dt><dd>${formatDate(m.due,{day:'numeric',month:'long',year:'numeric'})}</dd></div><div><dt>Project owner</dt><dd>${avatar(project(m.project).owner)}${person(project(m.project).owner).name}</dd></div></dl>${demoNote}`,`<button class="button button-primary" data-action="project" data-id="${m.project}">Explore project ${icon('arrow')}</button>`);break;}
  case 'export':exportSummary();break;
}});
document.addEventListener('change',event=>{const {id,value}=event.target;if(id==='project-status'){state.projectStatus=value;render();}if(id==='task-scope'){state.taskScope=value;render();}if(id==='task-status'){state.taskStatus=value;render();}if(id==='knowledge-type'){state.knowledgeType=value;render();}if(event.target.classList.contains('toggle'))toast('Preference updated for this preview only.');});
document.addEventListener('input',event=>{if(event.target.id==='global-search')search(event.target.value);});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;const data=Object.fromEntries(new FormData(form));if(form.id==='new-project-form'){if(!data.name.trim())return;DEMO.projects.push({id:'project-'+Date.now(),name:data.name.trim(),description:data.description.trim()||'A new possibility, ready to take shape.',category:'New initiative',owner:data.owner,members:[data.owner],status:'Planning',progress:0,due:data.due,color:'sage'});closeModal();state.projectStatus='all';location.hash='projects';render();toast('Your preview project is ready.');}else if(form.id==='new-task-form'){if(!data.title.trim())return;DEMO.tasks.push({...data,title:data.title.trim(),id:'FM-'+(101+DEMO.tasks.length)});closeModal();state.taskScope='all';state.taskStatus='all';location.hash='tasks';render();toast('Work added to this presentation.');}else if(form.id==='edit-task-form'){Object.assign(DEMO.tasks.find(t=>t.id===form.dataset.id),data);closeModal();render();toast('Work updated in this preview.');}else if(form.id==='settings-form'){toast('Preview saved. Settings reset when the page refreshes.');}else if(form.id==='reply-form'){closeModal();toast('Reply previewed. No message was sent.');}else if(form.id==='simple-form'){const kind=form.dataset.kind;if(!data.title.trim())return;if(kind==='invite'){closeModal();toast('Invitation previewed. No email was sent.');return;}if(kind==='document'){DEMO.documents.unshift({id:'d'+Date.now(),name:data.title.trim(),project:data.project,owner:'eleanor',type:'Guide',updated:'2026-11-16',size:'1 min read',content:data.content});location.hash='knowledge';state.knowledgeType='all';}if(kind==='discussion'){DEMO.discussions.unshift({id:'c'+Date.now(),title:data.title.trim(),project:data.project,author:'eleanor',replies:0,updated:'Just now',excerpt:data.content});location.hash='discussions';}if(kind==='milestone'){DEMO.milestones.push({id:'m'+Date.now(),title:data.title.trim(),project:data.project,due:data.due,status:'Upcoming'});DEMO.milestones.sort((a,b)=>a.due.localeCompare(b.due));location.hash='timeline';}closeModal();render();toast('Added to this preview. Changes reset on refresh.');}});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}if(event.key==='Escape')closeMenu();if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-action][tabindex="0"]')){event.preventDefault();event.target.click();}});
modal.addEventListener('click',event=>{if(event.target===modal){const rect=modal.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)closeModal();}});
document.getElementById('menu-button').addEventListener('click',()=>{const open=document.getElementById('sidebar').classList.toggle('open');document.getElementById('sidebar-backdrop').classList.toggle('visible',open);document.getElementById('menu-button').setAttribute('aria-expanded',String(open));});
document.getElementById('sidebar-backdrop').addEventListener('click',closeMenu);
document.getElementById('search-button').addEventListener('click',openSearch);
document.getElementById('notifications-button').addEventListener('click',()=>openModal('Your workspace, in the picture.','Recent updates and a little context for the day ahead.',`<div class="notification-list">${activityList()}</div>`));
['profile-button','top-profile-button'].forEach(id=>document.getElementById(id).addEventListener('click',()=>openPerson('eleanor')));
document.getElementById('organization-button').addEventListener('click',()=>openModal('Meridian & Co.','A sample organisation for this presentation.',`<p class="detail-description">A considered workspace for ${DEMO.people.length} colleagues and ${DEMO.projects.length} projects. Forma brings plans, delivery, conversations and knowledge into one clear view.</p>${demoNote}`,`<button class="button button-primary" data-action="close-modal">Back to the workspace</button>`));
window.addEventListener('hashchange',navigate);
hydrateIcons();navigate();
